// Generated by scripts/build.mjs. Only public static assets are cached.
const VERSION="46ae8b5817296c3a";
const BASE=new URL('./',self.location.href);
const PREFIX='schedule-public-'+encodeURIComponent(BASE.pathname)+'-';
const CACHE=PREFIX+VERSION;
const FILES=["index.html","manifest.webmanifest","assets/icon.svg","assets/icon-192.png","assets/icon-512.png","assets/service-app.css","assets/service-app.js","assets/service-translations.json","assets/service-config.js","assets/vendor/supabase.js","assets/vendor/LICENSE-supabase.txt","assets/pwa.js","assets/service-model.mjs"];
const URLS=FILES.map(file=>new URL(file,BASE).href);
const ALLOWED=new Set(URLS);
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(URLS))));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith(PREFIX)&&name!==CACHE)await caches.delete(name);await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data?.type==='SKIP_WAITING')self.skipWaiting();});
self.addEventListener('fetch',event=>{
  const request=event.request,url=new URL(request.url);
  if(request.method!=='GET'||url.origin!==BASE.origin)return;
  // Never cache auth redirects, token-bearing URLs, APIs or user-generated data.
  if(url.search||url.hash)return;
  const isHome=request.mode==='navigate'&&(url.pathname===BASE.pathname||url.pathname===new URL('index.html',BASE).pathname);
  // Keep the HTML and its assets on the same release until the user accepts an update.
  if(isHome){event.respondWith((async()=>{const cached=await caches.match(new URL('index.html',BASE).href,{cacheName:CACHE});return cached||fetch(request,{cache:'no-cache'});})());return;}
  if(!ALLOWED.has(url.href))return;
  event.respondWith((async()=>{const cached=await caches.match(url.href,{cacheName:CACHE});return cached||fetch(request);})());
});
